create table public.platform_announcements(id uuid primary key default gen_random_uuid(),titulo text not null,mensagem text not null,tipo text not null default 'info' check(tipo in('info','sucesso','atencao','critico')),destino text not null default 'todos' check(destino in('todos','clinica','plano')),destino_id text,inicia_em timestamptz not null default now(),termina_em timestamptz,publicado boolean not null default false,criado_por uuid not null references auth.users(id),created_at timestamptz not null default now(),check(destino='todos' or destino_id is not null));
create table public.platform_announcement_reads(announcement_id uuid references public.platform_announcements(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,lido_em timestamptz not null default now(),primary key(announcement_id,user_id));
alter table public.platform_announcements enable row level security;alter table public.platform_announcement_reads enable row level security;
create policy "plataforma gerencia comunicados" on public.platform_announcements for all to authenticated using(is_platform_admin()) with check(is_platform_admin() and criado_por=auth.uid());
create policy "usuario registra leitura" on public.platform_announcement_reads for insert to authenticated with check(user_id=auth.uid());create policy "usuario le confirmacoes" on public.platform_announcement_reads for select to authenticated using(user_id=auth.uid() or is_platform_admin());
create or replace function public.meus_comunicados() returns table(id uuid,titulo text,mensagem text,tipo text,inicia_em timestamptz,termina_em timestamptz,lido boolean) language sql security definer set search_path=public stable as $$ select a.id,a.titulo,a.mensagem,a.tipo,a.inicia_em,a.termina_em,exists(select 1 from platform_announcement_reads r where r.announcement_id=a.id and r.user_id=auth.uid()) from platform_announcements a left join profiles p on p.id=auth.uid() left join assinaturas_plano s on s.user_id=auth.uid() and s.status in('ativa','trial') where auth.uid() is not null and a.publicado and a.inicia_em<=now() and(a.termina_em is null or a.termina_em>now())and(a.destino='todos'or(a.destino='clinica'and a.destino_id=p.clinica_id::text)or(a.destino='plano'and a.destino_id=s.plano_slug))order by a.inicia_em desc;$$;grant execute on function public.meus_comunicados() to authenticated;

